1	type Item = { type: string; material?: string; cursed?: boolean; enchantment?: number };
2	
3	const enchantmentLevel = (item: Item): number => item.enchantment ?? 0;
4	
5	const basePremiumsByType: Record<string, number> = { sword: 100, amulet: 60, staff: 80, potion: 40, rune: 25, moonstone: 25 };
6	
7	const BLOCK_SIZE = 3;
8	const BLOCK_PREMIUM = 60;
9	
10	const sumBy = <T>(values: T[], valueOf: (value: T) => number): number =>
11	  values.reduce((sum, value) => sum + valueOf(value), 0);
12	
13	const basePremiumForItem = (item: Item): number => {
14	  const premium = basePremiumsByType[item.type];
15	  if (premium === undefined) {
16	    throw new Error(`Unknown item type: ${item.type}`);
17	  }
18	  return premium;
19	};
20	
21	const sumOfItemBasePremiums = (items: Item[]): number =>
22	  sumBy(items, basePremiumForItem);
23	
24	const groupByType = (items: Item[]): Item[][] => {
25	  const groups = new Map<string, Item[]>();
26	  for (const item of items) {
27	    const group = groups.get(item.type) ?? [];
28	    group.push(item);
29	    groups.set(item.type, group);
30	  }
31	  return [...groups.values()];
32	};
33	
34	const basePremiumForGroup = (group: Item[]): number =>
35	  group.length === BLOCK_SIZE ? BLOCK_PREMIUM : sumOfItemBasePremiums(group);
36	
37	export const basePremium = (items: Item[]): number =>
38	  sumBy(groupByType(items), basePremiumForGroup);
39	
40	const PROCESSING_FEE = 5;
41	
42	type Customer = { yearsWithMHPCO: number };
43	type QuoteStep = { op: "quote"; items: Item[] };
44	type Damage = { itemType: string; amount: number };
45	type ClaimStep = { op: "claim"; policy: number; incident: { cause: string; damages: Damage[] } };
46	type Step = QuoteStep | ClaimStep;
47	type Scenario = { customer: Customer; steps: Step[] };
48	
49	type QuoteResult = { premium: number };
50	type ClaimResult = { payout: number; remainingCap: number };
51	type StepResult = QuoteResult | ClaimResult;
52	
53	const CURSE_SURCHARGE_RATE = 0.5;
54	const HIGH_ENCHANTMENT_RATE = 0.3;
55	const HIGH_ENCHANTMENT_THRESHOLD = 5;
56	const FIRST_INSURANCE_RATE = 0.1;
57	const LOYALTY_RATE = 0.2;
58	const LOYALTY_THRESHOLD = 2;
59	const FOLLOWUP_RATE = 0.15;
60	
61	const surchargeOf = (item: Item, rate: number): number => basePremiumForItem(item) * rate;
62	
63	const curseSurchargeForItem = (item: Item): number =>
64	  item.cursed ? surchargeOf(item, CURSE_SURCHARGE_RATE) : 0;
65	
66	const curseSurcharge = (items: Item[]): number =>
67	  sumBy(items, curseSurchargeForItem);
68	
69	const highEnchantmentSurchargeForItem = (item: Item): number =>
70	  enchantmentLevel(item) >= HIGH_ENCHANTMENT_THRESHOLD
71	    ? surchargeOf(item, HIGH_ENCHANTMENT_RATE)
72	    : 0;
73	
74	const highEnchantmentSurcharge = (items: Item[]): number =>
75	  sumBy(items, highEnchantmentSurchargeForItem);
76	
77	const rateOfPolicyBase = (policyBase: number, rate: number): number => policyBase * rate;
78	
79	const firstInsuranceSurcharge = (policyBase: number): number =>
80	  rateOfPolicyBase(policyBase, FIRST_INSURANCE_RATE);
81	
82	const loyaltyDiscount = (policyBase: number, customer: Customer): number =>
83	  customer.yearsWithMHPCO >= LOYALTY_THRESHOLD ? rateOfPolicyBase(policyBase, LOYALTY_RATE) : 0;
84	
85	const followUpDiscount = (policyBase: number, isFollowUp: boolean): number =>
86	  isFollowUp ? rateOfPolicyBase(policyBase, FOLLOWUP_RATE) : 0;
87	
88	const itemSurcharges = (items: Item[]): number =>
89	  curseSurcharge(items) + highEnchantmentSurcharge(items);
90	
91	// MHPCO always keeps the fraction: a premium is money owed *to* MHPCO,
92	// so rounding up (a higher premium) lands the fraction in its favor.
93	const roundPremiumInFavorOfMHPCO = (premium: number): number => Math.ceil(premium);
94	
95	const quotePremium = (step: QuoteStep, customer: Customer, isFollowUp: boolean): number => {
96	  const policyBase = basePremium(step.items);
97	  const surcharges = itemSurcharges(step.items) + firstInsuranceSurcharge(policyBase);
98	  const discounts = loyaltyDiscount(policyBase, customer) + followUpDiscount(policyBase, isFollowUp);
99	  return roundPremiumInFavorOfMHPCO(policyBase + surcharges - discounts + PROCESSING_FEE);
100	};
101	
102	const DEDUCTIBLE = 100;
103	const CAP_MULTIPLIER = 2;
104	const REDUCED_REIMBURSEMENT_THRESHOLD = 8;
105	const REDUCED_REIMBURSEMENT_RATE = 0.5;
106	
107	const insuranceValuesByType: Record<string, number> = { sword: 1000, amulet: 600, staff: 800, potion: 400, rune: 250, moonstone: 250 };
108	
109	const insuranceValue = (item: Item): number => insuranceValuesByType[item.type];
110	
111	const insuranceSum = (items: Item[]): number =>
112	  sumBy(items, insuranceValue);
113	
114	const policyCap = (items: Item[]): number => insuranceSum(items) * CAP_MULTIPLIER;
115	
116	const reimbursableValue = (damageAmount: number, item: Item): number =>
117	  enchantmentLevel(item) >= REDUCED_REIMBURSEMENT_THRESHOLD
118	    ? damageAmount * REDUCED_REIMBURSEMENT_RATE
119	    : damageAmount;
120	
121	const insuredItemFor = (damage: Damage, items: Item[]): Item =>
122	  items.find((item) => item.type === damage.itemType) as Item;
123	
124	const payoutForDamage = (damage: Damage, items: Item[]): number =>
125	  reimbursableValue(damage.amount, insuredItemFor(damage, items)) - DEDUCTIBLE;
126	
127	// The deductible in payoutForDamage applies once per damage entry, so the
128	// incident payout is simply the sum across every damage in the incident.
129	const incidentPayout = (damages: Damage[], items: Item[]): number =>
130	  sumBy(damages, (damage) => payoutForDamage(damage, items));
131	
132	// MHPCO always keeps the fraction: a payout is money owed *by* MHPCO,
133	// so rounding down (a lower payout) lands the fraction in its favor.
134	const roundPayoutInFavorOfMHPCO = (payout: number): number => Math.floor(payout);
135	
136	const countByType = (types: string[]): Map<string, number> => {
137	  const counts = new Map<string, number>();
138	  for (const type of types) {
139	    counts.set(type, (counts.get(type) ?? 0) + 1);
140	  }
141	  return counts;
142	};
143	
144	const validateDamagesCovered = (damages: Damage[], items: Item[]): void => {
145	  const insuredCounts = countByType(items.map((item) => item.type));
146	  const damageCounts = countByType(damages.map((damage) => damage.itemType));
147	  for (const [type, damagedCount] of damageCounts) {
148	    const insuredCount = insuredCounts.get(type) ?? 0;
149	    if (damagedCount > insuredCount) {
150	      throw new Error(`Claim damages more ${type} items than are insured`);
151	    }
152	  }
153	};
154	
155	const claimResult = (step: ClaimStep, scenario: Scenario, alreadyPaid: number): ClaimResult => {
156	  const policyStep = scenario.steps[step.policy] as QuoteStep;
157	  validateDamagesCovered(step.incident.damages, policyStep.items);
158	  const capBeforeClaim = policyCap(policyStep.items) - alreadyPaid;
159	  const desiredPayout = roundPayoutInFavorOfMHPCO(incidentPayout(step.incident.damages, policyStep.items));
160	  const payout = Math.min(desiredPayout, capBeforeClaim);
161	  return { payout, remainingCap: capBeforeClaim - payout };
162	};
163	
164	export const runScenario = (scenario: Scenario): { results: StepResult[] } => {
165	  const paidByPolicy = new Map<number, number>();
166	  const results = scenario.steps.map((step, index) => {
167	    if (step.op === "quote") {
168	      return { premium: quotePremium(step, scenario.customer, index > 0) };
169	    }
170	    const alreadyPaid = paidByPolicy.get(step.policy) ?? 0;
171	    const result = claimResult(step, scenario, alreadyPaid);
172	    paidByPolicy.set(step.policy, alreadyPaid + result.payout);
173	    return result;
174	  });
175	  return { results };
176	};
